#!/usr/bin/env node
/**
 * Fetches Scripture text for every reference used in the content library
 * from a verifiable source and writes it to scripts/data/scripture-cache.json.
 *
 * Provider: bible-api.com, World English Bible (public domain).
 * Licensed translations (e.g. NLT) must be supplied by their licensed provider —
 * never typed from memory or generated by AI.
 *
 * Usage: node scripts/fetch-scripture.mjs [--translation web]
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const cachePath = join(root, 'scripts/data/scripture-cache.json');
const cards = JSON.parse(readFileSync(join(root, 'content/cards.json'), 'utf8'));

const translation = process.argv.includes('--translation')
  ? process.argv[process.argv.indexOf('--translation') + 1]
  : 'web';

const refs = new Set();
for (const card of cards) {
  for (const p of card.scripture.passages) refs.add(p.reference);
  for (const r of card.study?.relatedPassages ?? []) refs.add(r.reference);
}

const cache = existsSync(cachePath) ? JSON.parse(readFileSync(cachePath, 'utf8')) : {};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let fetched = 0;
for (const ref of refs) {
  const key = `${translation}:${ref}`;
  if (cache[key]) continue;
  const url = `https://bible-api.com/${encodeURIComponent(ref.replace(/–/g, '-'))}?translation=${translation}`;
  const res = await fetch(url);
  if (!res.ok) {
    console.error(`✗ ${ref}: HTTP ${res.status}`);
    await sleep(3000);
    continue;
  }
  const data = await res.json();
  cache[key] = {
    reference: ref,
    translation: data.translation_id,
    translationName: data.translation_name,
    license: data.translation_note,
    text: data.verses.map((v) => v.text.replace(/\s+/g, ' ').trim()).join(' '),
    verses: data.verses.map((v) => ({ verse: `${v.chapter}:${v.verse}`, text: v.text.replace(/\s+/g, ' ').trim() })),
    source: url,
    fetchedAt: new Date().toISOString(),
  };
  fetched++;
  console.log(`✓ ${ref}`);
  writeFileSync(cachePath, JSON.stringify(cache, null, 2));
  await sleep(2200); // stay well under the public API's rate limit
}

console.log(`Done. ${fetched} fetched, ${Object.keys(cache).length} cached.`);
